--
-- Accounts and sites (PLAT-12 plan 2.1; data §2.1, §2.4, §4.3, §8; domain model §2.1, §2.3;
-- ADR-0018, ADR-0025, ADR-0031). core_accounts gains the rest of its catalogue row (`settings`
-- arrived in 0012): country, default_locale and timezone with one value each in wave 0, limits
-- (AccountLimits; a missing key reads as the code default), provisioned_by (PLAT-13 writes it),
-- closed_at and version. It stays a platform table: elx_app keeps SELECT on its own row only (0003),
-- so the settings door writes it on the platform pool; elx_platform keeps every privilege (PLAT-13's
-- provisioning door, PLAT-12's settings door).
--
-- core_sites and core_usage_counters are tenant tables with the template policies of 0003, enabled
-- by core_enable_tenant_rls() when the job runs with ELX_RLS=on. elx_app keeps the default
-- SELECT, INSERT, UPDATE, DELETE of 0001 on both (the site doors and DEL-2's order counter run in
-- the tenant unit of work); elx_platform may only read them in wave 0 (plan 2.1: the platform
-- console's site doors are PLAT-13's and grant what they need). core_sites.point is PostGIS
-- geometry(Point, 4326) with a GiST index (data §8); core_usage_counters is keyed by
-- (account_id, metric, period), period being the month start in Asia/Riyadh.
CREATE TABLE "core_sites" (
	"id" uuid PRIMARY KEY NOT NULL,
	"account_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"name_ar" text NOT NULL,
	"name_en" text NOT NULL,
	"address_text" text,
	"national_address_short_code" text,
	"point" geometry(Point,4326),
	"opening_hours" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "core_sites_kind_check" CHECK ("core_sites"."kind" IN ('branch', 'warehouse', 'both')),
	CONSTRAINT "core_sites_status_check" CHECK ("core_sites"."status" IN ('active', 'inactive')),
	CONSTRAINT "core_sites_national_address_short_code_check" CHECK ("core_sites"."national_address_short_code" ~ '^[A-Z]{4}[0-9]{4}$'),
	CONSTRAINT "core_sites_version_check" CHECK ("core_sites"."version" >= 1)
);
