	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "core_usage_counters_pkey" PRIMARY KEY("account_id","metric","period"),
	CONSTRAINT "core_usage_counters_metric_check" CHECK ("core_usage_counters"."metric" IN ('orders', 'drivers', 'sites', 'api_keys')),
	CONSTRAINT "core_usage_counters_value_check" CHECK ("core_usage_counters"."value" >= 0)
);
